#!/usr/bin/env bash
set -Eeuo pipefail

# Adds a native Windows desktop runtime to P59-Tuningh without replacing the
# existing Android application.
#
# Run from the repository root:
#   chmod +x add_windows_runtime.sh
#   ./add_windows_runtime.sh
#
# Optional:
#   SKIP_BUILD=1 ./add_windows_runtime.sh
#   VERIFY_ANDROID=1 ./add_windows_runtime.sh

ROOT="${1:-$PWD}"
cd "$ROOT"

for required in settings.gradle.kts build.gradle.kts; do
    if [[ ! -f "$required" ]]; then
        echo "ERROR: Missing $required"
        echo "Run this script from the P59-Tuningh repository root."
        exit 1
    fi
done

for command in python3 base64 sha256sum; do
    if ! command -v "$command" >/dev/null 2>&1; then
        echo "ERROR: Required command is missing: $command"
        exit 1
    fi
done

STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP_DIR=".windows-runtime-backup-$STAMP"
PAYLOAD_DIR="$(mktemp -d)"
SUCCESS=0

mkdir -p "$BACKUP_DIR"

AFFECTED_PATHS=(
    "settings.gradle.kts"
    "build.gradle.kts"
    "windowsApp"
    ".github/workflows/build-windows-runtime.yml"
    "LICENSES/PCM_HAMMER_GPL-3.0.txt"
    "THIRD_PARTY_NOTICES_WINDOWS.md"
)

: > "$BACKUP_DIR/existing-paths.txt"
: > "$BACKUP_DIR/new-paths.txt"

for path in "${AFFECTED_PATHS[@]}"; do
    if [[ -e "$path" ]]; then
        printf '%s\n' "$path" >> "$BACKUP_DIR/existing-paths.txt"
        cp -a --parents "$path" "$BACKUP_DIR"
    else
        printf '%s\n' "$path" >> "$BACKUP_DIR/new-paths.txt"
    fi
done

rollback() {
    local status=$?
    trap - EXIT
    rm -rf "$PAYLOAD_DIR"

    if [[ $status -ne 0 && $SUCCESS -eq 0 ]]; then
        echo
        echo "ERROR: Windows runtime installation failed. Restoring the repository..."

        while IFS= read -r path; do
            [[ -z "$path" ]] && continue
            rm -rf "$path"
            mkdir -p "$(dirname "$path")"
            cp -a "$BACKUP_DIR/$path" "$path"
        done < "$BACKUP_DIR/existing-paths.txt"

        while IFS= read -r path; do
            [[ -z "$path" ]] && continue
            rm -rf "$path"
        done < "$BACKUP_DIR/new-paths.txt"

        echo "Rollback complete. Backup retained at $BACKUP_DIR"
    fi

    exit "$status"
}
trap rollback EXIT

mkdir -p "$PAYLOAD_DIR"

mkdir -p "$PAYLOAD_DIR/windowsApp"
base64 -d > "$PAYLOAD_DIR/windowsApp/build.gradle.kts" <<'PAYLOAD_1'
cGx1Z2lucyB7CiAgICBpZCgib3JnLmpldGJyYWlucy5rb3RsaW4uanZtIikKICAgIGFwcGxpY2F0
aW9uCn0KCmdyb3VwID0gImNvbS5wNTkiCnZlcnNpb24gPSAiMS4wLjAiCgpyZXBvc2l0b3JpZXMg
ewogICAgbWF2ZW5DZW50cmFsKCkKfQoKZGVwZW5kZW5jaWVzIHsKICAgIGltcGxlbWVudGF0aW9u
