# Patch Gradle project registration without changing the Android module.
python3 <<'PY'
from pathlib import Path
import re

settings_path = Path("settings.gradle.kts")
settings = settings_path.read_text(encoding="utf-8")

if 'include(":windowsApp")' not in settings:
    if not settings.endswith("\n"):
        settings += "\n"
    settings += 'include(":windowsApp")\n'
    settings_path.write_text(settings, encoding="utf-8")

build_path = Path("build.gradle.kts")
build = build_path.read_text(encoding="utf-8")

plugin_line = '    id("org.jetbrains.kotlin.jvm") version "1.9.22" apply false\n'

if 'id("org.jetbrains.kotlin.jvm")' not in build:
    marker = '    id("org.jetbrains.kotlin.android") version "1.9.22" apply false\n'

    if marker in build:
        build = build.replace(marker, marker + plugin_line, 1)
    else:
        match = re.search(r'plugins\s*\{', build)
        if not match:
            raise SystemExit("ERROR: Could not find the root plugins block")
        insert = match.end()
        build = build[:insert] + "\n" + plugin_line + build[insert:]

    build_path.write_text(build, encoding="utf-8")
PY

# Install the reviewed module payload.
for source in \
    "$PAYLOAD_DIR/windowsApp" \
    "$PAYLOAD_DIR/.github"; do
    if [[ -e "$source" ]]; then
        cp -a "$source"/. "${source#"$PAYLOAD_DIR/"}"/
    fi
done

# Ensure exact destinations when the target parent did not previously exist.
mkdir -p windowsApp .github/workflows
cp -a "$PAYLOAD_DIR/windowsApp"/. windowsApp/
cp "$PAYLOAD_DIR/.github/workflows/build-windows-runtime.yml" \
   .github/workflows/build-windows-runtime.yml

# Package the official read-only P01/P59 kernel.
KERNEL_DEST="windowsApp/src/main/resources/kernel_p01.bin"
ANDROID_KERNEL="app/src/main/res/raw/kernel_p01.bin"
UPSTREAM_COMMIT="6db97fc545ad9fc9d35f752a87e447b555040685"
MAX_KERNEL_BYTES=$((0x4E00))

mkdir -p "$(dirname "$KERNEL_DEST")" LICENSES

USE_EXISTING_KERNEL=0
if [[ -s "$ANDROID_KERNEL" && -s "LICENSES/PCM_HAMMER_GPL-3.0.txt" ]]; then
    KERNEL_SIZE="$(stat -c %s "$ANDROID_KERNEL")"
    if (( KERNEL_SIZE >= 256 && KERNEL_SIZE <= MAX_KERNEL_BYTES )); then
        cp "$ANDROID_KERNEL" "$KERNEL_DEST"
        USE_EXISTING_KERNEL=1
        echo "Using the checked Android P01/P59 kernel already present in the repository."
    fi
fi

if [[ $USE_EXISTING_KERNEL -eq 0 ]]; then
    for command in git make m68k-linux-gnu-gcc; do
        if ! command -v "$command" >/dev/null 2>&1; then
            if ! command -v apt-get >/dev/null 2>&1; then
                echo "ERROR: $command is missing and apt-get is unavailable."
                exit 1
            fi

            APT=(apt-get)
            if command -v sudo >/dev/null 2>&1; then
                APT=(sudo apt-get)
            fi

            echo "Installing the Motorola 68k kernel build tools..."
            "${APT[@]}" update
            DEBIAN_FRONTEND=noninteractive "${APT[@]}" install -y \
                gcc-m68k-linux-gnu make git
            break
        fi
    done

    UPSTREAM_DIR="$(mktemp -d)"
    git init -q "$UPSTREAM_DIR"
    git -C "$UPSTREAM_DIR" remote add origin \
        https://github.com/PcmHammer/PcmHammer.git
    git -C "$UPSTREAM_DIR" fetch -q --depth 1 origin "$UPSTREAM_COMMIT"
    git -C "$UPSTREAM_DIR" checkout -q --detach FETCH_HEAD

    ACTUAL_COMMIT="$(git -C "$UPSTREAM_DIR" rev-parse HEAD)"
    if [[ "$ACTUAL_COMMIT" != "$UPSTREAM_COMMIT" ]]; then
        echo "ERROR: PCM Hammer commit verification failed."
        exit 1
    fi

    (
        cd "$UPSTREAM_DIR/Kernels"
        mkdir -p build
        make -f makefile-assembly \
            PREFIX=/usr/bin/m68k-linux-gnu- \
            pcm=P01 \
            address=FF8000 \
            srcdir=68k-VPW-Asm
    )

    BUILT_KERNEL="$UPSTREAM_DIR/Kernels/build/Kernel-P01.bin"
    if [[ ! -s "$BUILT_KERNEL" ]]; then
        echo "ERROR: Kernel-P01.bin was not built."
        exit 1
    fi

    KERNEL_SIZE="$(stat -c %s "$BUILT_KERNEL")"
    if (( KERNEL_SIZE < 256 || KERNEL_SIZE > MAX_KERNEL_BYTES )); then
        echo "ERROR: Built kernel size $KERNEL_SIZE is outside P01/P59 RAM limits."
        exit 1
    fi

    cp "$BUILT_KERNEL" "$KERNEL_DEST"

    if [[ -f "$UPSTREAM_DIR/LICENSE" ]]; then
        cp "$UPSTREAM_DIR/LICENSE" LICENSES/PCM_HAMMER_GPL-3.0.txt
    elif [[ -f "$UPSTREAM_DIR/COPYING" ]]; then
        cp "$UPSTREAM_DIR/COPYING" LICENSES/PCM_HAMMER_GPL-3.0.txt
    else
        echo "ERROR: PCM Hammer license file was not found."
        exit 1
    fi

    rm -rf "$UPSTREAM_DIR"
fi

KERNEL_SIZE="$(stat -c %s "$KERNEL_DEST")"
KERNEL_SHA256="$(sha256sum "$KERNEL_DEST" | awk '{print $1}')"

cat > THIRD_PARTY_NOTICES_WINDOWS.md <<NOTICE
# Windows runtime third-party notices

## PCM Hammer

The Windows runtime includes a compiled P01/P59 read kernel and read-only
protocol behavior derived from PCM Hammer.

- Project: https://github.com/PcmHammer/PcmHammer
- Revision: \`$UPSTREAM_COMMIT\`
- Kernel: \`windowsApp/src/main/resources/kernel_p01.bin\`
- Kernel size: \`$KERNEL_SIZE bytes\`
- Kernel SHA-256: \`$KERNEL_SHA256\`
- License: GPL-3.0-only
- License copy: \`LICENSES/PCM_HAMMER_GPL-3.0.txt\`

The P59 DVI reader files contain their own SPDX license headers.
NOTICE

# Static checks before invoking Gradle.
grep -q 'include(":windowsApp")' settings.gradle.kts
grep -q 'id("org.jetbrains.kotlin.jvm")' build.gradle.kts
grep -q 'com.fazecast:jSerialComm:2.11.4' windowsApp/build.gradle.kts
grep -q 'class ElmLiveDataClient' \
    windowsApp/src/main/kotlin/com/p59/windows/ElmLiveDataClient.kt
grep -q 'class P59KernelReader' \
    windowsApp/src/main/kotlin/com/p59/windows/protocol/P59KernelReader.kt
grep -q 'PCM writing remains disabled' windowsApp/README.md

if [[ "${SKIP_BUILD:-0}" != "1" ]]; then
    if ! command -v javac >/dev/null 2>&1 || ! javac -version 2>&1 | grep -Eq '^javac 17(\.|$)'; then
        if command -v apt-get >/dev/null 2>&1; then
            APT=(apt-get)
            if command -v sudo >/dev/null 2>&1; then
                APT=(sudo apt-get)
            fi

            echo "Installing Java 17 toolchain for Gradle..."
            "${APT[@]}" update
            DEBIAN_FRONTEND=noninteractive "${APT[@]}" install -y openjdk-17-jdk
        else
            echo "ERROR: Java 17 (javac 17) is required, and apt-get is unavailable to install it."
            exit 1
        fi
    fi

    if [[ -x /usr/lib/jvm/java-17-openjdk-amd64/bin/javac ]]; then
        export JAVA_HOME=/usr/lib/jvm/java-17-openjdk-amd64
        export PATH="$JAVA_HOME/bin:$PATH"
    fi

    WRAPPER_JAR="gradle/wrapper/gradle-wrapper.jar"

    if [[ -x ./gradlew && -f "$WRAPPER_JAR" ]]; then
        GRADLE=(./gradlew --no-daemon)
    elif command -v gradle >/dev/null 2>&1; then
        if [[ ! -f "$WRAPPER_JAR" ]]; then
            echo "Gradle wrapper jar is missing. Bootstrapping wrapper with system Gradle..."
            gradle --no-daemon wrapper
        fi

        if [[ -x ./gradlew && -f "$WRAPPER_JAR" ]]; then
            GRADLE=(./gradlew --no-daemon)
        else
            GRADLE=(gradle --no-daemon)
        fi
    else
        echo "ERROR: Missing Gradle wrapper jar ($WRAPPER_JAR), and no system gradle found."
        exit 1
    fi

    echo
    echo "Compiling and testing the Windows runtime..."
    "${GRADLE[@]}" \
        :windowsApp:clean \
        :windowsApp:test \
        :windowsApp:installDist

    if [[ "${VERIFY_ANDROID:-0}" == "1" ]]; then
        echo
        echo "Verifying the existing Android debug build..."
        "${GRADLE[@]}" :app:assembleDebug
    fi
fi

SUCCESS=1

echo
echo "============================================================"
echo "WINDOWS RUNTIME ADDED"
echo
echo "Module: windowsApp"
echo "Kernel SHA-256: $KERNEL_SHA256"
echo
echo "Run in Codespaces/Linux for compile validation:"
echo "  ./gradlew :windowsApp:test :windowsApp:installDist"
echo
echo "Run on Windows:"
echo "  .\\gradlew.bat :windowsApp:run"
echo
echo "Build EXE/MSI on Windows:"
echo "  powershell -ExecutionPolicy Bypass -File windowsApp\\package-windows.ps1"
echo
echo "GitHub Actions workflow:"
echo "  Actions > Build Windows Runtime > Run workflow"
echo
echo "Windows functions:"
echo "  - COM-port connection"
echo "  - live PCM data"
echo "  - DTC read/clear"
